mapper.update:
update club_membership_setting
set enabled = #{enabled}, version = version + 1,
    update_by = #{updateBy}, update_time = #{updateTime}
where club_id = #{clubId} and version = #{version}

mapper.select:
select * from club_membership_term
where club_id = #{clubId} and member_id = #{memberId}
order by starts_at desc, id desc

select * from club_membership_term
where club_id = #{clubId} and member_id = #{memberId}
  and status not in ('CANCELLED','REFUNDED') and grace_ends_at > #{now}
order by starts_at asc, id asc for update

select * from club_membership_term
where club_id = #{clubId}
  and status not in ('CANCELLED','REFUNDED') and grace_ends_at > #{now}
order by member_id asc, starts_at asc, id asc for update

mapper.update:
update club_membership_term set status = #{status}, version = version + 1, update_time = #{updateTime}
where id = #{id} and club_id = #{clubId} and member_id = #{memberId}
  and version = #{version} and status not in ('CANCELLED','REFUNDED')

UPDATE club_membership_invoice
SET verified_payment_fact_id=#{factId}, verified_payment_fact_hash=CAST(#{factHash} AS BINARY)
WHERE id=#{id} AND status='PAID' AND transaction_id=#{transactionId}
  AND amount_fen=#{amountFen} AND snapshot_hash=#{snapshotHash}
  AND verified_payment_fact_id IS NULL AND verified_payment_fact_hash IS NULL
